139	    @Override
140	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
141	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
142	        if (currentOwner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        normalizeEmail(ownerFieldsDto);
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
151	        currentOwner.setEmail(ownerFieldsDto.getEmail());
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
