220	    /**
221	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
222	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
223	     * Validation already rejects {@code null} values and the pattern-constrained fields
224	     * when blank, but {@code address} and {@code city} have no pattern, so a
225	     * whitespace-only value would otherwise slip through.
226	     *
227	     * @param ownerFieldsDto the submitted owner fields
228	     * @throws RequiredFieldsMissingException if any required field is missing or blank
229	     */
230	    /**
231	     * Common street-type abbreviations expanded during address normalization. Keys are the
232	     * upper-cased abbreviation tokens; values are their canonical expansions.
233	     */
234	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
235	        "ST", "STREET",
236	        "RD", "ROAD",
237	        "AVE", "AVENUE");
238	
239	    /**
240	     * Normalizes the submitted address on create and writes the canonical value back onto the
241	     * request so it is persisted, echoed back, and used for every downstream address comparison
242	     * (household duplicate detection and the household id). The value is trimmed, internal
243	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
244	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
245	     * {@code null} address is left untouched so the required-field check can report it as missing.
246	     *
247	     * @param ownerFieldsDto the submitted owner fields
248	     */
249	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
250	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
251	    }
252	
253	    /**
254	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
255	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
256	     * expanded to its full form. A {@code null} value is returned unchanged.
257	     *
258	     * @param raw the address to canonicalize, possibly {@code null}
259	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
260	     */
261	    private static String normalizeAddress(String raw) {
262	        if (raw == null) {
263	            return null;
264	        }
265	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
266	        if (collapsed.isEmpty()) {
267	            return collapsed;
268	        }
269	        String[] tokens = collapsed.split(" ");
270	        StringBuilder sb = new StringBuilder(collapsed.length());
271	        for (int i = 0; i < tokens.length; i++) {
272	            if (i > 0) {
273	                sb.append(' ');
274	            }
275	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
276	        }
277	        return sb.toString();
278	    }
279	
280	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
281	        List<String> errors = new ArrayList<>();
282	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
283	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
284	        requireText("address", ownerFieldsDto.getAddress(), errors);
285	        requireText("city", ownerFieldsDto.getCity(), errors);
286	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
287	        if (!errors.isEmpty()) {
288	            throw new RequiredFieldsMissingException(errors);
289	        }
290	    }
291	
292	    private static void requireText(String field, String value, List<String> errors) {
293	        if (value == null || value.isBlank()) {
294	            errors.add(field);
295	        }
296	    }
297	
298	    /**
299	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
300	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
301	     * and echoed back in that form.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields
304	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
305	     *                                        valid E.164 number
306	     */
307	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
308	        String e164 = toE164(ownerFieldsDto.getTelephone());
309	        if (e164 == null) {
310	            throw new RequiredFieldsMissingException(List.of("telephone"));
311	        }
312	        ownerFieldsDto.setTelephone(e164);
313	    }
314	
315	    /**
316	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
317	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
318	     * and country code are present they are kept; otherwise country code {@code '+61'} is
319	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
320	     * must contain 8 to 15 digits after the {@code '+'}.
321	     *
322	     * @param raw the submitted telephone, possibly {@code null}
323	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
324	     */
325	    private static String toE164(String raw) {
326	        if (raw == null) {
327	            return null;
328	        }
329	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
330	        String digits;
331	        if (cleaned.startsWith("+")) {
332	            digits = cleaned.substring(1);
333	        } else {
334	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
335	            digits = "61" + national;
336	        }
337	        if (!digits.matches("[0-9]{8,15}")) {
338	            return null;
339	        }
340	        return "+" + digits;
341	    }
342	
343	    /**
344	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
345	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
346	     * each stored owner's telephone is normalized the same way before comparison so differing
347	     * input formats collapse to the same value.
348	     *
349	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
350	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
351	     *                                     same E.164 telephone
352	     */
353	    /**
354	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
355	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
356	     * the parts may contain whitespace or a second {@code @}.
357	     */
358	    private static final Pattern EMAIL_PATTERN =
359	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
360	
361	    /**
362	     * Normalizes the submitted email when present: the value is trimmed, required to be a
363	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
364	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
365	     *
366	     * @param ownerFieldsDto the submitted owner fields
367	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
368	     */
369	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
370	        String email = ownerFieldsDto.getEmail();
371	        if (email == null) {
372	            return;
373	        }
374	        String trimmed = email.strip();
375	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
376	            throw new InvalidEmailException(email);
377	        }
378	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
379	    }
380	
381	    /**
382	     * Establishes the effective registration date on create and rolls it onto a business day.
383	     * When the client does not supply a {@code registrationDate} it defaults to the server's
384	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
385	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
386	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
387	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
388	     * the membership number's year segment and the daily create-limit).
389	     *
390	     * @param ownerFieldsDto the submitted owner fields
391	     */
392	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
393	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
394	        if (effective == null) {
395	            effective = LocalDate.now();
396	        }
397	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
398	    }
399	
400	    /**
401	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
402	     * following Monday; any weekday is returned unchanged.
403	     *
404	     * @param date the date to adjust
405	     * @return the same date when it is a weekday, otherwise the next Monday
406	     */
407	    private static LocalDate toBusinessDay(LocalDate date) {
408	        return switch (date.getDayOfWeek()) {
409	            case SATURDAY -> date.plusDays(2);
410	            case SUNDAY -> date.plusDays(1);
411	            default -> date;
412	        };
413	    }
414	
415	    /**
416	     * Assigns the owner's {@code customerCode} on create, formatted
417	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
418	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
419	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
420	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
421	     *
422	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
423	     */
424	    private void assignCustomerCode(Owner owner) {
425	        String city = owner.getCity();
426	        String lastName = owner.getLastName();
427	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
428	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
429	        long sequence = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
431	            .count() + 1;
432	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
433	    }
434	
435	    /**
436	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
437	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
438	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
439	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
440	     * canonicalized fields, every owner in the same household — including one joining an existing
441	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
442	     * order.
443	     *
444	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
445	     */
446	    private void assignHouseholdId(Owner owner) {
447	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
448	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
449	    }
450	
451	    /**
452	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
453	     * already share this owner's {@code firstName} and {@code lastName}, compared
454	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
455	     * pre-existing namesakes.
456	     *
457	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
458	     */
459	    private void assignNamesakeCount(Owner owner) {
460	        String firstName = owner.getFirstName();
461	        String lastName = owner.getLastName();
462	        long count = this.clinicService.findAllOwners().stream()
463	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
464	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
465	            .count();
466	        owner.setNamesakeCount((int) count);
467	    }
468	
469	    /**
470	     * Assigns the owner's {@code membershipNumber} on create, formatted
471	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
472	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
473	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
474	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
475	     *
476	     * @param owner the owner being created (with its {@code customerCode} and
477	     *              {@code registrationDate} already set)
478	     */
479	    private void assignMembershipNumber(Owner owner) {
480	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
481	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
482	    }
483	
484	    /**
485	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
486	     *
487	     * @param value the string to hash
488	     * @return the 64-character lower-case hex digest
489	     */
490	    private static String sha256Hex(String value) {
491	        try {
492	            byte[] digest = MessageDigest.getInstance("SHA-256")
493	                .digest(value.getBytes(StandardCharsets.UTF_8));
494	            StringBuilder sb = new StringBuilder(digest.length * 2);
495	            for (byte b : digest) {
496	                sb.append(String.format("%02x", b));
497	            }
498	            return sb.toString();
499	        }
500	        catch (NoSuchAlgorithmException e) {
501	            throw new IllegalStateException("SHA-256 not available", e);
502	        }
503	    }
504	
505	    private void rejectDuplicateTelephone(String normalizedTelephone) {
506	        boolean duplicate = this.clinicService.findAllOwners().stream()
507	            .map(Owner::getTelephone)
508	            .map(OwnerRestControllerV1::toE164)
509	            .filter(telephone -> telephone != null)
510	            .anyMatch(normalizedTelephone::equals);
511	        if (duplicate) {
512	            throw new DuplicateTelephoneException(normalizedTelephone);
513	        }
514	    }
515	
516	    /**
517	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
518	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
519	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
520	     * still counts as the same household. The check is skipped when the request opts in via
521	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
522	     * the existing one.
523	     *
524	     * @param ownerFieldsDto the submitted owner fields
525	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
526	     *                                     last name and address and the request did not opt in
527	     */
528	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
529	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
530	            return;
531	        }
532	        String lastName = collapse(ownerFieldsDto.getLastName());
533	        String address = collapse(ownerFieldsDto.getAddress());
534	        boolean duplicate = this.clinicService.findAllOwners().stream()
535	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
536	                && collapse(owner.getAddress()).equals(address));
537	        if (duplicate) {
538	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
539	        }
540	    }
541	
542	    /**
543	     * The maximum number of owners permitted in a single city. A create is rejected once the
544	     * owner's city already contains this many owners.
545	     */
546	    private static final long CITY_CAPACITY = 50;
547	
548	    /**
549	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
550	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
551	     * before this owner is persisted.
552	     *
553	     * @param city the submitted city
554	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
555	     */
556	    private void rejectCityAtCapacity(String city) {
557	        long count = this.clinicService.findAllOwners().stream()
558	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
559	            .count();
560	        if (count >= CITY_CAPACITY) {
561	            throw new CityAtCapacityException(city);
562	        }
563	    }
564	
565	    /**
566	     * The maximum number of owners permitted to be created in a single day. A create is
567	     * rejected once this many owners already carry today's {@code registrationDate}.
568	     */
569	    private static final long DAILY_LIMIT = 100;
570	
571	    /**
572	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
573	     * business day as their {@code registrationDate}. The day counted against is this create's
574	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
575	     * so owners are counted per adjusted business day. The count is taken before this owner is
576	     * persisted.
577	     *
578	     * @param businessDay the effective, business-day-adjusted registration date of this create
579	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
580	     */
581	    private void rejectDailyLimit(LocalDate businessDay) {
582	        long count = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
584	            .count();
585	        if (count >= DAILY_LIMIT) {
586	            throw new DailyOwnerLimitExceededException(businessDay);
587	        }
588	    }
589	
590	    /**
591	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
592	     * every internal run of whitespace is collapsed to a single space, and the result is
593	     * lower-cased. A {@code null} value collapses to the empty string.
594	     *
595	     * @param value the value to canonicalize, possibly {@code null}
596	     * @return the collapsed, lower-cased value
597	     */
598	    private static String collapse(String value) {
599	        if (value == null) {
600	            return "";
601	        }
602	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
603	    }
604	
605	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
606	    @Override
607	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
608	        Owner owner = this.clinicService.findOwnerById(ownerId);
609	        if (owner != null) {
610	            Pet pet = owner.getPet(petId);
611	            if (pet != null) {
612	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
613	            }
614	        }
615	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
616	    }
617	}
